insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('chilojo-cliffs','ZWE','Chilojo Cliffs, Gonarezhou','Gonarezhou — “Place of Elephants”','rock',-21.65,31.75,'Banded red-and-ochre sandstone cliffs rising high above the Runde River in Gonarezhou National Park.','Iconic of Zimbabwe''s southeast lowveld, the cliffs blaze crimson at sunset. They''re part of the Great Limpopo Transfrontier Park, which links Zimbabwe, South Africa and Mozambique.','Height','up to ~180 m',false,true,10,'{"color":"#E63946","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Zimbabwe_Gonarezhou_Landscape_Chilojo_Cliffs.jpg","credit":"Ralf Ellerich","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Zimbabwe_Gonarezhou_Landscape_Chilojo_Cliffs.jpg"}]}'::jsonb,null,'[]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('epworth-balancing-rocks','ZWE','Epworth Balancing Rocks',null,'rock',-17.89,31.15,'Granite boulders stacked in impossible-looking towers just outside Harare, shaped by millions of years of weathering.','They once appeared on Zimbabwe''s banknotes, a natural sculpture garden that seems to defy gravity.','Near','Harare',false,true,11,'{"color":"#FFB703","intensity":0.6,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Chiremba_Balancing_Rocks_-_Harare3500.jpg/1280px-Chiremba_Balancing_Rocks_-_Harare3500.jpg","credit":"lumoplank","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Chiremba_Balancing_Rocks_-_Harare3500.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Chiremba_Balancing_Rocks_-_Harare3512.jpg/1280px-Chiremba_Balancing_Rocks_-_Harare3512.jpg","credit":"lumoplank","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Chiremba_Balancing_Rocks_-_Harare3512.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Bankbiljet_van_tweehonderd_miljoen_Zimbabwaanse_dollars%2C_NG-2016-4-C.jpg/1280px-Bankbiljet_van_tweehonderd_miljoen_Zimbabwaanse_dollars%2C_NG-2016-4-C.jpg","credit":"Rijksmuseum","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Bankbiljet_van_tweehonderd_miljoen_Zimbabwaanse_dollars,_NG-2016-4-C.jpg"}]}'::jsonb,null,'[]'::jsonb)
